sql.q1:
```
SELECT COUNT(*) FROM issues WHERE state = 'open' AND (LOWER(title) LIKE '%security%' OR LOWER(body) LIKE '%security%');
```

sql.q2:
```
SELECT COUNT(*) FROM issues WHERE is_pr = 1;
```

sql.q3:
```
SELECT SUM(comments) FROM issues WHERE state = 'closed';
```

sql.q4:
```
SELECT user, COUNT(*) as count FROM issues WHERE is_pr = 1 GROUP BY user ORDER BY count DESC LIMIT 1;
```

sql.q5:
```
SELECT number FROM issues WHERE state = 'open' AND is_pr = 0 AND comments > 5 ORDER BY number;
```

sql.q6:
```
SELECT COUNT(DISTINCT value) FROM issues, json_each(issues.labels) WHERE issues.labels IS NOT NULL;
```

sql.q7:
```
SELECT COUNT(*) FROM issues WHERE state = 'open' AND labels LIKE '%"bug"%';
```

sql.q9:
```
SELECT COUNT(*) FROM (SELECT user FROM issues WHERE is_pr = 1 INTERSECT SELECT user FROM issues WHERE is_pr = 0);
```

sql.q10:
```
SELECT ROUND(AVG(comments), 2) FROM issues WHERE state = 'open' AND is_pr = 0;
```
